import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // ключ берётся из ANTHROPIC_API_KEY

async function main() {
  const text = "Модель никогда не видит слов или букв, только числа.";

  // 1. До вызова: сколько входных токенов уйдёт (бесплатно, свой лимит)
  const { input_tokens } = await client.messages.countTokens({
    model: "claude-sonnet-5",
    messages: [{ role: "user", content: text }],
  });
  console.log("will send", input_tokens, "input tokens");

  // 2. После вызова: точные цифры, по которым выставят счёт
  const msg = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 300, // жёсткий потолок на ВЫХОДНЫЕ токены
    messages: [{ role: "user", content: text }],
  });
  console.log(msg.usage.input_tokens, msg.usage.output_tokens, msg.stop_reason);
}

main();

import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic(); // reads ANTHROPIC_API_KEY from env

async function main() {
  const text = "Модель никогда не видит слов или букв, только числа.";

  // 1. Before the call: how many input tokens you will send (free, own rate limit)
  const { input_tokens } = await client.messages.countTokens({
    model: "claude-sonnet-5",
    messages: [{ role: "user", content: text }],
  });
  console.log("will send", input_tokens, "input tokens");

  // 2. After the call: the exact numbers you are billed for
  const msg = await client.messages.create({
    model: "claude-sonnet-5",
    max_tokens: 300, // hard cap on OUTPUT tokens
    messages: [{ role: "user", content: text }],
  });
  console.log(msg.usage.input_tokens, msg.usage.output_tokens, msg.stop_reason);
}

main();
